// TH18 v1.00a Stage 2 MainSub04 / Cir01 (st02.ecl.txt:72-130, 1208-1227).
// F门创建按已批准的击破速度奖励波固定为完整 75 次计划创建（15 轮 x 5 只）。
// 源坐标；角度按 BAM 保存。训练外壳：控制敌 (0,0)、无敌、禁体碰，真实敌保留源判定。
const TIME_LIMIT: int = 2400;
const TH18_BALL2: int = 432; // etSprite type 5 Ball2, color 4

// Cir01_at: st02.ecl.txt:100-130. Easy 不启动本任务（106 行 !NHL）。
async sub shots() {
    var rank: int = global(GVAR_RANK);
    var first: int = 10 + rand(10);
    var speed: fx = 3fx;
    if rank == 1 {
        first = 10 + rand(200); // 105 行
        speed = 2.5fx;          // etSpeedD 第二档
    } else if rank == 3 {
        speed = 4fx;            // etSpeedD 第四档；首等仍 10+rand(10)
    }
    wait(first);
    sh_reset(0);
    sh_sprite(0, TH18_BALL2, 4); // 115 行 etSprite(0,5,4)
    sh_aim(0, 1);                // 114 行 etAim(0,0)
    sh_ring(0, 0);
    sh_count(0, 1, 1);           // 116 行 etCountD 四档均为 1x1
    sh_angle(0, 0deg, 0deg);     // 117 行
    sh_speed(0, speed, 0fx);     // 118 行 etSpeedD 四档首速 1/2.5/3/4
    for i in 0..3 {              // 121/124-127 行 $A=3，每次 etOn 后等待
        sh_fire(0);
        wait(10 + rand(60));
    }
}

// Cir01: st02.ecl.txt:72-99. REL 椭圆 s=0、轴为设置时的 ABS 角快照。
async sub cir01() {
    set_invuln(65535);
    set_hitbox(8fx);   // 77 行 setHitbox(16,16)
    set_hurtbox(14fx); // 76 行 setHurtbox(28,28)，源伤害取半径一半
    // 83 行 moveVel(pi/2 + RANDF2*0.17453292, 3.0)
    var axis_i: int = 16384 + (rand(65536) - 32768) * 1820 / 32768;
    var axis: angle = axis_i as angle;
    // 85 行 moveEllipseRel(RANDRAD, 0.034906585, 20, 0, ABS_ANGLE, 0)
    var theta: int = rand(65536);
    var bx: fx = $self_x;
    var by: fx = $self_y;
    var rel: fx = 20fx * sin((theta - axis_i) as angle);
    move_to(0, bx - rel * sin(axis), by + rel * cos(axis), EASE_LINEAR);
    if global(GVAR_RANK) >= 1 {
        spawn shots(); // 87 行 !NHL 异步发射
    }
    var turn: int = 0;
    var k: int = 0;
    loop {
        // 89-91 行 wait(180); moveSpeedTime(120,0,1.0); moveAngleTime(120,0,ANGLE_PLAYER)
        if k == 180 {
            turn = (aim_player() as int) - axis_i;
            if turn > 32768 { turn = turn - 65536; }
            if turn < -32768 { turn = turn + 65536; }
        }
        var next: int = k + 1;
        // 84 行 moveSpeedTime(120,0,0.5)：3.0 -> 0.5
        var speed: fx = 0.5fx;
        if next <= 120 { speed = 3fx - 2.5fx * (next as fx) / 120; }
        // 90-91 行：0.5 -> 1.0 同时转向自机
        if next > 180 && next <= 300 { speed = 0.5fx + 0.5fx * ((next - 180) as fx) / 120; }
        if next > 300 { speed = 1fx; }
        var heading: int = axis_i;
        if next > 180 && next <= 300 { heading = axis_i + turn * (next - 180) / 120; }
        if next > 300 { heading = axis_i + turn; }
        bx = bx + speed * cos(heading as angle);
        by = by + speed * sin(heading as angle);
        theta = theta + 364; // 0.034906585 rad/frame
        rel = 20fx * sin((theta - axis_i) as angle);
        var nx: fx = bx - rel * sin(axis);
        var ny: fx = by + rel * cos(axis);
        move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
        k = next;
        wait(1);
    }
}

// MainSub04: st02.ecl.txt:1208-1227. 15 轮、每轮 5 次创建、间隔 20。
async sub pattern() {
    wait(120); // 开段 120 帧缓冲
    for r in 0..15 {
        _ = spawn_enemy((rand(32768) as fx) / 256 - 64fx, -48fx, 140, 0, 0, 0, cir01); // 1214
        wait(20);
        _ = spawn_enemy(64fx + (rand(32768) as fx) / 256 - 64fx, -48fx, 140, 0, 0, 0, cir01); // 1216
        wait(20);
        _ = spawn_enemy(-64fx + (rand(32768) as fx) / 256 - 64fx, -48fx, 140, 0, 0, 0, cir01); // 1218
        wait(20);
        _ = spawn_enemy(-120fx + (rand(32768) as fx) / 256 - 64fx, -48fx, 140, 0, 0, 0, cir01); // 1220
        wait(20);
        _ = spawn_enemy(120fx + (rand(32768) as fx) / 256 - 64fx, -48fx, 140, 0, 0, 0, cir01); // 1222
        wait(20);
    }
    loop { wait(600); }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(600); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 10000, 0, 0, 0, control);
    loop { wait(600); }
}
